/* User-supplied visual direction, connected to Bandora's existing practice engine. */
(function(){
  'use strict';
  const navigation=[['overview','Overview'],['tests','Test tickets'],['notebook','Notebook'],['progress','Progress'],['plan','Study plan'],['resources','Resources']];
  renderShell=function(){
    const user=currentUser();
    $('#app').innerHTML=`<header class="bd-header"><div class="bd-header-inner">${brand}<nav class="bd-navigation" aria-label="Main navigation">${navigation.map(([p,label])=>`<button data-action="nav" data-page="${p}" ${page===p?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="bd-account">${user?`<button class="avatar" data-work="account" aria-label="Account settings">${esc(userName().slice(0,2).toUpperCase())}</button>`:button('Log in','nav','secondary small-btn','data-page="auth"')}</div></div></header><div class="main-shell bd-main"><main id="main">${page==='overview'?dashboard():page==='tests'?testsPage():page==='progress'?progressPage():page==='plan'?studyPlan():page==='notebook'?notebookPage():resourcesPage()}</main><footer class="footnote"><span>Bandora · Original IELTS Academic practice</span><span>Independent preparation · <a href="https://ielts.org/take-a-test/test-types/ielts-academic-test" target="_blank" rel="noopener">Official test format ↗</a></span></footer></div>`;
    if(page==='notebook')window.PracticeTools?.bindNotebook();
  };
  dashboard=function(){
    const ticket=TestTickets.find(t=>Object.values(t.sections).some(id=>!saved.history.some(h=>h.setId===id&&!h.questionIds)))||TestTickets[0];
    const last=saved.history.find(h=>h.total&&!h.questionIds);
    const done=Object.values(ticket.sections).filter(id=>saved.history.some(h=>h.setId===id&&!h.questionIds)).length;
    const progress=Math.round(done/4*100);
    return `<section class="bd-hero"><div class="bd-hero-copy"><span class="bd-announcement"><b>10 full tickets</b> All four Academic IELTS skills</span><h1>Your next band<br>starts <em>right here.</em></h1><p>Make test day feel more familiar. Practise complete tests, build your confidence and learn from every answer.</p><span class="bd-module">${icon('check')} IELTS Academic</span><div class="bd-hero-actions">${button('Choose a full ticket '+icon('arrow'),'nav','primary','data-page="tests"')}${active?button('Resume session','resume','secondary'):button('View my progress','nav','secondary','data-page="progress"')}</div><div class="bd-hero-benefits"><span>${icon('check')} Free guest practice</span><span>${icon('check')} Answers saved as you go</span></div></div><div class="bd-snapshot"><div class="bd-snapshot-top"><div><span class="bd-mini-label">YOUR NEXT PRACTICE</span><h2>${esc(ticket.title)} · Academic</h2></div><span class="tag green">${done}/4 completed</span></div><div class="bd-snapshot-summary"><div class="bd-progress-ring" style="--ticket-progress:${progress}%"><div><strong>${done}<small>/4</small></strong><span>SECTIONS</span></div></div><div><h3>A clear path forward.</h3><p>${done?'Your completed sections are saved. Pick up where you left off.':'Four skills, one complete ticket. Start with Listening or choose a section below.'}</p></div></div><div class="bd-snapshot-sections">${Object.entries(ticket.sections).map(([type,id])=>`<button data-action="intro" data-type="${type}" data-set="${id}" data-mode="exam"><span class="bd-skill-symbol ${type}">${icon(modules[type].icon)}</span><span><strong>${names[type]}</strong><small>${TestLibrary.get(type,id).count}</small></span><span>${saved.history.some(h=>h.setId===id&&!h.questionIds)?icon('check'):icon('arrow')}</span></button>`).join('')}</div><div class="bd-snapshot-note">${last?`Latest ${names[last.type]} result: <strong>${last.score}/${last.total}</strong> correct`:'Instant Reading & Listening results · Writing & Speaking self-review'}</div></div></section><section class="bd-stat-band" aria-label="Practice library"><div><strong>10</strong><span>complete test tickets</span></div><div><strong>800</strong><span>scored practice questions</span></div><div><strong>20</strong><span>Writing tasks with visuals</span></div><div><strong>30</strong><span>guided Speaking parts</span></div></section><section class="practice-section"><div class="section-heading"><div><span class="eyebrow">FOUR SKILLS. ONE GOAL.</span><h2>Make every session count.</h2></div>${button('Explore all tickets '+icon('arrow'),'nav','secondary small-btn','data-page="tests"')}</div><div class="skill-grid">${skillCards()}</div></section><section class="bd-how"><div><span class="eyebrow">PRACTISE. REVIEW. REPEAT.</span><h2>Small steps.<br><em>Stronger skills.</em></h2><p>Use exam mode for timed practice or take things at your own pace.</p></div><ol><li><span>01</span><div><h3>Choose your test</h3><p>Ten original tickets, each with all four Academic sections.</p></div></li><li><span>02</span><div><h3>Find your focus</h3><p>Work through full passages, audio, visual tasks and speaking prompts.</p></div></li><li><span>03</span><div><h3>Learn from your answers</h3><p>Review explanations, revisit mistakes and save your results.</p></div></li></ol></section><div class="lower-grid"><section class="card activity-card"><div class="section-heading"><div><h2>Your recent practice</h2><p>Progress starts with showing up.</p></div>${button('View all','nav','secondary small-btn','data-page="progress"')}</div>${recentList()}</section><aside class="next-step-card"><span class="eyebrow">YOUR PERSONAL STUDY PLAN</span><h3>A little practice.<br>A little closer.</h3><p>Your daily intention is ${saved.dailyGoal||20} minutes. Build a routine around your own pace.</p><button class="btn primary" data-action="nav" data-page="plan">Open study plan ${icon('arrow')}</button></aside></div><p class="bd-honesty">Original practice materials. Listening uses browser-generated audio. Scores are practice results, not calibrated IELTS bands; Writing and Speaking use self-review.</p>`;
  };
})();
